#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Timing;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.antiGravityPad_Evoke)]
    public class AntiGravityPad_Evoke : ContraptionEvokeBehaviour
    {
        public AntiGravityPad_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            entity.SetEvoked(true);
            var timer = AntiGravityPad.GetEvocationTimer(entity);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(EVOCATION_SECONDS);
                AntiGravityPad.SetEvocationTimer(entity, timer);
            }
            else
            {
                timer.ResetSeconds(EVOCATION_SECONDS);
            }
            entity.PlaySound(VanillaSoundID.magnetic);
        }
        public const float EVOCATION_SECONDS = 5;
    }
}
